INSERT INTO RIVERFLOW.sys_plugin VALUES (2063929712232636417, 'i西安网关调用', 'ixa-gateway', '1.0.0', 'both', 'gateway', '通过 GatewaySender SDK 调用 i西安网关接口，获取 jsapi token 或执行业务接口', 'river-ixa-gateway-1.0.0-SNAPSHOT.jar', '/xazwfw/chengxu/riverflow/plugins/1780914166677_river-ixa-gateway-1.0.0-SNAPSHOT.jar', 6811522, 'Connection', 'enabled', 1, '{"authCode":"","method":"ixa.app.jsapi.getToken","appIv":"your-app-iv","appId":"your-app-id","readTimeout":1000,"ixaUrl":"http://gateway.ixa.example.com","appKey":"your-app-key","appSecret":"your-app-secret","params":"{}","connTimeout":1000}', NULL, NULL, '2026-06-08 18:22:44', '2026-06-08 18:22:47', NULL, NULL, 0);
INSERT INTO RIVERFLOW.sys_plugin VALUES (2064266225395032065, '二维码认证', 'qrcode', '1.0.0', 'both', 'auth', '二维码生成、状态检查、扫码标记、结果存储与查询（含完整状态机）', 'river-qrcode-plugin-1.0.0-SNAPSHOT.jar', '/xazwfw/chengxu/riverflow/plugins/1780994394978_river-qrcode-plugin-1.0.0-SNAPSHOT.jar', 3136663, 'Grid', 'enabled', 1, '{"operation":"generate","content":"${context.h5Url}?qrId={qrId}&bizId={bizId}","size":300,"expireSeconds":300,"scanExtendSeconds":300,"bizId":"${context.bizId}","queryQrId":"${context.qrId}","pollTimeout":120,"authStatus":"SUCCESS","userName":"","idCard":"","phone":"","namespace":"","encryptKey":"","secretKey":""}', NULL, NULL, '2026-06-09 16:39:55', '2026-06-09 16:39:55', NULL, NULL, 0);
